mapper.select:
/* 대국민포털_게시물기본 게시판 조회권한 검증 (PstMapper.pstAuthCheck) */
SELECT EXISTS (
   SELECT 1
     FROM kids_own.TB_PP_M_BBS b
        , kids_own.TB_PP_M_BBS_AUTHRT ba
    WHERE b.bbs_id = #{bbsId}
      AND ba.authrt_cd = 'BBS_USR'
      AND b.use_yn = 'Y'
      AND b.bbs_id = ba.bbs_id
)

mapper.update:
/* 대국민포털_게시물기본 조회수 증가 (PstMapper.updtInqCnt) */
UPDATE kids_own.TB_PP_M_PST
SET pst_inq_cnt = COALESCE(pst_inq_cnt, 0) + 1
WHERE bbs_id = #{bbsId}		
AND pst_sn = #{pstSn}
